"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7075],{31115:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates an animal pen, deriving its `AnimalPenConfig` from the pen\'s item\\ndata. Asserts that the item exists and declares both `maxCapacity` and\\n`maxAnimals`.","params":[{"name":"propData","desc":"","lua_type":"AnimalPenBaseClass.PropData"}],"returns":[{"desc":"","lua_type":"AnimalPen"}],"function_type":"static","source":{"line":45,"path":"src/Shared/Class/Base/Props/AnimalPen.luau"}}],"properties":[],"types":[],"name":"AnimalPen","desc":"Concrete animal pen prop. The only thing this layer does is turn item data\\ninto a pen config: it reads `maxCapacity` and `maxAnimals` out of the pen\'s\\nentry in the `Pens` table and hands them to [AnimalPenBaseClass], which\\nholds all the actual behaviour.\\n\\nEvery pen tier (small, large, and so on) is this same class with different\\nitem data, so adding a tier means adding a `Pens` entry, not a module.\\n\\nThe three asserts are deliberate: a pen with no capacity limits would produce\\ndrops without bound, so a missing config fails at construction rather than\\nshipping a broken economy.\\n\\nGated by [FeatureFlags].BaseEnabled \u2014 disabled by default; per-project forks\\nenable it deliberately.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","tags":["dormant"],"source":{"line":23,"path":"src/Shared/Class/Base/Props/AnimalPen.luau"}}')}}]);